const picks=[['pentaryn-seafoot-maps.scenes','HrKj6ZgWJGkM9g7j','Drow Prison (Devils Hold Prison)',true],
['pentaryn-seafoot-maps.scenes','6Hs4FHhWYhgSK605','Underdark Caverns',true],
['pentaryn-seafoot-maps.scenes','pfEPZgXH5MSaUL2W','Fungal Caverns (glowing shrooms)',false],
['pentaryn-seafoot-maps.scenes','1AgMbJuXGpgoD9wx','Underdark Abyss',true],
['pentaryn-seafoot-maps.scenes','QHhh2i8Uy70qYTtz','The Tangled Caverns (webs)',true],
['pentaryn-seafoot-maps.scenes','tbY9HU5nR4XcH3RQ','Fallen Dungeon of Bron’Darha',true],
['pentaryn-seafoot-maps.scenes','YJ3FMDmBrXNLkteP','Ruined Dwarven Vaults',true]];
