  await s.update({'environment.darknessLevel':1,'environment.darknessLock':true,'environment.globalLight.enabled':false,tokenVision:true,'fog.exploration':true});
  out.push({id:s.id,name:s.name,walls:s.walls.size,doors:s.walls.filter(w=>w.door>0).length,lights:s.lights.size,dark:s.environment.darknessLevel,global:s.environment.globalLight.enabled});
}
return out;

if (game.world.id!=='pentaryn') return 'wrong world';
