if(!same) return {same, kp:[kp.width,kp.height], s:[s.width,s.height]};
try{ await s.deleteEmbeddedDocuments('Wall', s.walls.map(w=>w.id)); }catch(e){}
const walls=kp.walls.map(({_id,...w})=>w);
try{ await s.createEmbeddedDocuments('Wall', walls); }catch(e){}
const src=s._source; const doors=src.walls.filter(w=>w.door>0);
return {walls:src.walls.length, doors:doors.length, locked:doors.filter(w=>w.ds===2).length, closed:doors.filter(w=>w.ds===0).length};

