const core = await import('/modules/pentaryn-ties/known-core.mjs');
const plans = [
 ['IxcfWOvpcKID6bdn', [['cavenshistory', ["Who he is"]], ['brenfen', null], ['fenwardensofbrenfen', null], ['cavenshistory', null]]],
 ['pfCQRWnqsQjkZQnB', [['taloshistory', ["Who he is"]], ['thegroundstruck', ["Two sayings","Grounded","The crime","Naming your star","The worst thing you can say","The sentence","The new star"]], ['stardruids', null]]]
];
const out = {};
for (const [actorId, plan] of plans) {
  const pc = game.actors.get(actorId);
  const granted = foundry.utils.deepClone(pc.getFlag('pentaryn-ties','granted') ?? {});
  let t0 = Date.now(); const wrote = [];
  for (const [attrId, labels] of plan) {
    const entry = A.describe(attrId);
    for (const row of entry.lore) {
      if (labels && !labels.includes(row.label)) continue;
      const k = `attr:${attrId}:${row.id}`; if (granted[k]) continue;
      granted[k] = { text: row.text, when: t0++, icon: entry.icon, source: `${entry.title} — ${row.label}` };
      wrote.push(`${attrId}:${row.label}`);
    }
  }
  await pc.update({ 'flags.pentaryn-ties.granted': granted });
  const g = pc.getFlag('pentaryn-ties','granted');
  out[pc.name] = { n: wrote.length, per: Object.fromEntries(A.of(pc, null, {viewer: pc}).filter(r => r.authored).map(r => [r.id, core.grantsForEntry(g, '', {attributeIds:[r.id]}).map(x => x.source.split(' — ')[1])])) };
}
return out;

if (game.world.id !== 'pentaryn') return 'WRONG WORLD';
const A = game.pentaryn.ties.attributes, S = game.pentaryn.ties.study;
const core = await import('/modules/pentaryn-ties/known-core.mjs');
const marrith = game.actors.get('RNDTDBlFXxZ7Uc8i'), caven = game.actors.get('IxcfWOvpcKID6bdn');
const fid = (attrId, label) => A.describe(attrId).lore.find(r => r.label === label).id;
const log = [];
const ident = async (subject, attrId, pc) => {
  const r = await S.share({ ns: 'ident', subjectId: subject.id, attrId }, [pc], { notify: false });
  const st = core.identifiedState(game.actors.get(subject.id).flags['pentaryn-ties'].beliefs ?? {}, pc.id, attrId);
  log.push(['ident', pc.name, '->', subject.name, attrId, r.ok, r.reason ?? null, r.shared, r.skipped, 'carries=' + st.carries]);
  return st.carries === true;
};
const fact = async (subject, attrId, label, pc) => {
  const r = await S.share({ ns: 'attr', subjectId: subject.id, attrId, factId: fid(attrId, label) }, [pc], { notify: false });
  log.push(['attr', pc.name, '->', subject.name, attrId, label, r.ok, r.reason ?? null, r.shared, r.skipped, r.unseen]);
};
// Caven about Marrith
if (await ident(marrith, 'witchesofelderholt', caven)) {
  for (const l of ['Leave the witches alone', 'Two paths', 'Witches walk']) await fact(marrith, 'witchesofelderholt', l, caven);
  if (await ident(marrith, 'marrithshistory', caven)) for (const l of ['The capture', 'Who she came for']) await fact(marrith, 'marrithshistory', l, caven);
}
// Marrith about Caven
let ok = true;
for (const id of ['brenfen', 'fenwardensofbrenfen', 'cavenshistory']) { if (ok) ok = await ident(caven, id, marrith); }
if (ok) for (const l of ['Who he is', 'The drow libraries', 'The witch']) await fact(caven, 'cavenshistory', l, marrith);
return log;

