  if (lvl !== 5 && lvl !== 6) continue;
  const acts = d.system.activities ? Array.from(d.system.activities.values()) : [];
  const dmg = new Set();
  for (const a of acts) {
    for (const p of (a.damage?.parts ?? [])) {
      for (const t of (p.types ?? [])) dmg.add(t);
    }
  }
  const plain = (d.system.description?.value ?? "").replace(/<[^>]+>/g, " ").replace(/&\w+;/g, " ").replace(/\s+/g, " ").trim();
  out.push({
    name: d.name, level: lvl, school: d.system.school,
    classes: d.system.source?.custom ?? null,
    labels: d.labels?.classes ?? null,
    dmg: Array.from(dmg),
    fireText: /\bfire\b/i.test(plain), flameText: /flame|burn|heat/i.test(plain),
    uuid: d.uuid,
    desc: plain.slice(0, 220)
  });
}
out.sort((a,b)=> a.level-b.level || a.name.localeCompare(b.name));
return { count: out.length, keys: Object.keys(docs[0].system), out };

